insert into public.services
  (title, slug, short_description, full_description, deliverables, target_audience, icon, display_order, is_featured, image, meta_title, meta_description, focus_keyword)
values
  ('Taxation Consultancy Services', 'taxation-consultancy', 'Clear support for tax filings, reviews, planning, and conversations with the tax authority.', 'Tax questions rarely arrive in a neat order. We help businesses make sense of their filings, notices, transactions, and decisions before a small issue becomes an expensive one.', array['Tax Planning and Strategy', 'Corporate and Individual Income Tax Return Filing', 'Monthly VAT and Withholding Tax Compliance'], 'SMEs, Corporations, Exporters, and High-Net-Worth Individuals', 'ReceiptText', 1, true, '/services/service-tax.jpg', 'Taxation Consultancy Services | CA Narahari Adhikari', 'Strategic corporate tax advisory, return filings, VAT, TDS, and dispute resolution in Nepal.', 'Tax Advisory Nepal'),
  ('Audit and Assurance', 'audit-and-assurance', 'Audit and assurance services that improve transparency, stakeholder trust, and regulatory compliance.', 'An audit should leave you with a clearer understanding of the business. We review records, controls, and decisions behind the numbers and explain what needs attention.', array['Regulatory and Statutory Audit', 'Risk-Based Internal Audit', 'Donor and Project Audit', 'Tax Audit and Compliance Audit'], 'Listed Companies, Banks, INGOs, and Manufacturing Entities', 'ShieldCheck', 2, true, '/services/service-audit.jpg', 'Audit and Assurance Services in Nepal | CA Narahari Adhikari', 'Rigorous statutory audits, risk reviews, and financial assurance in Nepal.', 'Audit Services Nepal'),
  ('Mergers and Acquisitions', 'mergers-and-acquisitions', 'Support for transaction reviews, due diligence, valuations, and merger or acquisition execution.', 'A merger or acquisition changes more than the shareholding. It affects contracts, people, tax positions, reporting, and how the combined business operates.', array['Pre-Merger Advisory', 'Financial Due Diligence', 'Future Projections and Synergy Assessment'], 'Acquirers, Institutional Investors, and Growing Enterprises', 'Handshake', 3, true, '/services/service-ma.jpg', 'Mergers and Acquisitions Advisory | CA Narahari Adhikari', 'Due diligence, valuation, deal structuring, and M&A integration in Nepal.', 'M&A Nepal'),
  ('Advisory Services', 'advisory-services', 'Guidance for planning, evaluating options, and making informed decisions as your organisation changes.', 'Sometimes a business needs an outside view before it changes direction. We work with owners and finance teams on practical questions behind growth, risk, controls, and cash.', array['Management Consulting', 'Standard Operating Procedure Formulation', 'Public Procurement Policy Compliance'], 'Business Owners, Directors, and Finance Executives', 'MessageSquareQuote', 4, true, '/services/service-advisory.jpg', 'Business Advisory and Management Consulting | CA Narahari Adhikari', 'SOP formulation, governance reviews, fraud risk assessments, and management advisory.', 'Business Advisory Nepal'),
  ('Business Support and Outsourcing', 'business-support-outsourcing', 'Reliable back-office support for records, filings, and approvals that keep a business moving.', 'We take care of recurring records, filings, and administrative work so owners and finance teams can focus on the business.', array['Company Registration and Business Setup', 'Foreign Direct Investment Approvals', 'Financial Bookkeeping and Monthly Reporting'], 'Foreign Investors, Startups, Wholesalers, and Multinational Entities', 'HeartHandshake', 5, true, '/services/service-bpo.jpg', 'Business Support and Outsourcing in Nepal | CA Narahari Adhikari', 'Outsourced bookkeeping, payroll, company registration, and FDI approval facilitation.', 'Outsourcing Nepal'),
  ('NFRS and IFRS Implementation', 'nfrs-ifrs-implementation', 'Support with financial reporting policies, transition planning, and NFRS or IFRS requirements.', 'NFRS and IFRS work is easier when the team knows what changes, why it changes, and what evidence supports the final numbers.', array['NFRS and IFRS Adoption Roadmap', 'Opening Balance Sheet Preparation', 'Sector-Specific Implementation'], 'Listed Entities, Financial Institutions, Insurance, and Hydropower', 'LineChart', 6, true, '/services/service-ifrs.jpg', 'NFRS and IFRS Implementation Advisory | CA Narahari Adhikari', 'Technical guidance, GAAP reconciliation, and Nepal Financial Reporting Standards support.', 'NFRS Implementation Nepal'),
  ('Training and Seminar', 'training-and-seminar', 'Practical sessions for teams on taxation, financial reporting, business structuring, and compliance.', 'Our sessions are built around work people actually have to do: prepare a filing, read a standard, improve a control, or explain a financial decision.', array['Taxation and VAT Compliance Workshops', 'NFRS and IFRS Technical Standards', 'Business Structuring and M&A Strategy'], 'Finance Teams, Accountants, Corporate Boards, and Industry Associations', 'GraduationCap', 7, true, '/services/service-training.jpg', 'Corporate Training and Seminars | CA Narahari Adhikari', 'Hands-on workshops on Nepal taxation, VAT, NFRS reporting, and corporate compliance.', 'Corporate Training Nepal')
